%root_path = fileparts(mfilename("fullpath"));
%root_path = pwd;
[NG_FFCutsFits,FileResName] = recover_selected_cuts('NG_FFCutsFits','e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');
fn = fieldnames(NG_FFCutsFits);
save_result = false;
for i=1:numel(fn)
    fldVal  = NG_FFCutsFits.(fn{i});
    if iscell(fldVal) && isscalar(fldVal) && isa(fldVal{1},'sqw')
        save_result = true;
        NG_FFCutsFits.(fn{i}) = fldVal{1};
    end
end
if save_result
    save(FileResName,'NG_FFCutsFits','-v7.3');
end


fit_res_field = 'all_fit_par';
separate_fig  = false; % if true, detach 1D figures from live script

%%
[S_op110,J_op110,G_op110,Sq_op110,proj110minFF]= display_EiDep_blocks(NG_FFCutsFits, ... %[output:group:5e2a3821] %[output:0e3eec81] %[output:3c99ec2b] %[output:51575c16]
    'off110NGminFF',' <110> min FF change',fit_res_field,separate_fig); %[output:group:5e2a3821] %[output:0e3eec81] %[output:3c99ec2b] %[output:51575c16]


[S_maEi800,J_maEi800,Gam_maEi800,S_maEi800q] = extract_fit_par( ...
    NG_FFCutsFits.(['Ei800_off110NGmaxFF_',fit_res_field]));
proj200maxFF = NG_FFCutsFits.Ei200_off200NGmaxFF.data.proj;

plot_fp(separate_fig,'min FF change for low dE max FF for Ei800', ... %[output:group:7b4e549a] %[output:42ed33b8] %[output:3c52dd20] %[output:05a98bf2]
    [S_op110,S_maEi800], ... %[output:42ed33b8] %[output:3c52dd20] %[output:05a98bf2]
    [J_op110,J_maEi800], ... %[output:42ed33b8] %[output:3c52dd20] %[output:05a98bf2]
    [G_op110,Gam_maEi800]); %[output:group:7b4e549a] %[output:42ed33b8] %[output:3c52dd20] %[output:05a98bf2]
%%
bg_dataNGEi200 = extract_bg_par(NG_FFCutsFits.(['Ei200_off110NGminFF_',fit_res_field]),1);
bg_dataNGEi400 = extract_bg_par(NG_FFCutsFits.(['Ei400_off110NGminFF_',fit_res_field]),1);
bg_dataNGEi800mi = extract_bg_par(NG_FFCutsFits.(['Ei800_off110NGminFF_',fit_res_field]),1);
%bg_dataNGEi800ma = extract_bg_par(NG_FFCutsFits.(['Ei800_off200NGmaxFF_',fit_res_field]),1);
bg_dataNGEi800ma = extract_bg_par(NG_FFCutsFits.(['Ei800_off110NGmaxFF_',fit_res_field]),1);

plot_fp(separate_fig,'line-q fit bg for different Ei',[], ... %[output:group:981d7022] %[output:2956d259]
    [bg_dataNGEi200,bg_dataNGEi400,bg_dataNGEi800mi,bg_dataNGEi800ma]) %[output:group:981d7022] %[output:2956d259]
%
%%
[~,bg_dataNGEi200] = fit_IXDsBg_helper(bg_dataNGEi200,[],true,'g'); %[output:0d2779ac] %[output:300ea40c]
[~,bg_dataNGEi400] = fit_IXDsBg_helper(bg_dataNGEi400,[],true,'b'); %[output:5f3c5431] %[output:3439e905] %[output:76c7f01f]
[~,bg_dataNGEi800mi] = fit_IXDsBg_helper(bg_dataNGEi800mi,[55,235],true,'r');
[~,bg_dataNGEi800ma] = fit_IXDsBg_helper(bg_dataNGEi800ma,[55,235],true,'k');
%%
% remove calculated backgrounds
spp.Ei200_off110NGminNbg = NG_FFCutsFits.Ei200_off110NGminFF - ...
    sqw_eval(NG_FFCutsFits.Ei200_off110NGminFF,@linterp_bg,bg_dataNGEi200);
spp.Ei200_off110NGminNbg = cut(spp.Ei200_off110NGminNbg, ...
    [-0.35,0.005,0],[],SymopReflection('normvec',[-1,1,0],'offset',[1,1,0]));
plot(spp.Ei200_off110NGminNbg); lz 0 1; keep_figure %[output:138fc495]

spp.Ei400_off110NGminNbg = NG_FFCutsFits.Ei400_off110NGminFF - ...
    sqw_eval(NG_FFCutsFits.Ei400_off110NGminFF,@linterp_bg,bg_dataNGEi400);
spp.Ei400_off110NGminNbg = cut(spp.Ei400_off110NGminNbg,[-0.5,0.005,0],[],SymopReflection('normvec',[-1,1,0],'offset',[1,1,0]));
plot(spp.Ei400_off110NGminNbg); lz 0 1; keep_figure %[output:6c144bc3]

spp.Ei800_off110NGminNbg = NG_FFCutsFits.Ei800_off110NGminFF - ...
    sqw_eval(NG_FFCutsFits.Ei800_off110NGminFF,@linterp_bg,bg_dataNGEi800mi);
spp.Ei800_off110NGminNbg = cut(spp.Ei800_off110NGminNbg, ...
    [-0.5,0.005,0],[],SymopReflection('normvec',[-1,1,0],'offset',[1,1,0]));
plot(spp.Ei800_off110NGminNbg); lz 0 1; keep_figure %[output:7803a9a7]

