cuts_rangesNG = containers.Map();
cuts_rangesNG('Ei200_off110NGminNbg')  = [0;110];
cuts_rangesNG('Ei400_off110NGminNbg') = [110;170];
cuts_rangesNG('Ei800_off110NGminNbg') = [170;250];
%cuts_rangesNG('Ei800_off200NGmaxNbg') = [250;390];
cuts_rangesNG('Ei800_off110NGmaxNbg') = [250;350];

[w2,fh] = build_disp_in_dir_with_ds(spp,cuts_rangesNG,[-0.5,0.005,0],false); %[output:2e0427d9] %[output:9f444f44]
