data_ranges  = [data_ranges{:}];
pan_data = struct('data_ranges',data_ranges,'combined_ds',w2);
%save('NG_0p5_0p5_0_dataMFF','pan_data');
fh.UserData = w2.data;

%%

%plot(spp.Ei800_off200NGmaxNbg); lz 0 0.1;keep_figure; %[output:569eea8e]
plot(spp.Ei800_off110NGmaxNbg); lz 0 0.1;keep_figure;
