sppCr.Ei800_off110NGmaxNbg = magi.correct_mag_ff(spp.Ei800_off110NGmaxNbg);
plot(sppCr.Ei800_off110NGmaxNbg); lz 0 1; keep_figure %[output:6f0d3bbc]


[w2,fh] = build_disp_in_dir_with_ds(sppCr,cuts_rangesNG,0.01,0.5,false); %[output:508a3640] %[output:57350be2]
data_ranges = cuts_rangesNG.values;
data_ranges  = [data_ranges{:}];
pan_data = struct('data_ranges',data_ranges,'combined_ds',w2);
save('NG_0p5_0p5_0_dataMFF','pan_data');

%%
gamma=10;Seff0=0.7917;
%J0=39; J1=35; % GP
J0 = 52; J1 = 20; %  NG
correct_ff = 1;
gap = 0;    %
init_fg_param = [correct_ff,8,gamma,Seff0,  0,   J0, J1,  0,  0,  0];
%init_fg_params = [coffect_ff,T,gamma,Seff, gap, J0, J1, J2, J3, J4];
free_sw_param  =  [0          0, 1   ,1   , 0,    1, 1,   0,  0,  0];


keys = cuts_rangesNG.keys();
n_cuts = 0;
cut_ranges = struct();
for keyIndex = 1:numel(keys)
    currentKey = keys{keyIndex};
    range = cuts_rangesNG(currentKey);
    min_range = 30;
    if contains(currentKey,'Ei400')
        min_range = 40;
    end
    if contains(currentKey,'Ei800')
        min_range = 70;
    end    
    if range(1)<min_range
        range(1) = min_range;
    end
    cut_ranges.(currentKey) = range; 
    n_cuts = n_cuts + floor(range(2)-range(1))/10;
end
cuts = cell(1,n_cuts);
cutIdx = 0;
en = zeros(1,n_cuts);
for keyIndex = 1:numel(keys)
    currentKey = keys{keyIndex};
    range = cut_ranges.(currentKey);
    ncc = floor(range(2)-range(1))/10 - 1;
    for i=1:ncc
        cutIdx =cutIdx+1;
        cuts{cutIdx} = cut(spp.(currentKey),[],[range(1)+(i-1)*10,range(1)+i*10]);
        en(cutIdx) = range(1)+5+10*(i-1);
        %plot(cuts{cutIdx});
    end
end
cuts = cuts(1:cutIdx);
%%

kk = tobyfit(cuts{:});
kk = kk.set_local_foreground;
kk = kk.set_fun(@sqw_iron);

hkl_proj = spp.Ei800_off200NGmaxNbg.data.proj;
kk = kk.set_pin({init_fg_param,hkl_proj});
kk = kk.set_free(free_sw_param);

kk = kk.set_bind({{6,[6,1]},{7,[7,1]}});

%kk = kk.set_bfun (@linear_bg1D); % set_bfun sets the background functions
%
%bg_param = init_bg_param(valid);
%kk = kk.set_bpin (bg_param);  % initial background constant and gradient
%kk = kk.set_bfree (bfree);

kk = kk.set_options('list',2);

[fit_obj,fit_par] = kk.fit(); %[output:8abdefa3] %[output:9895dbb6] %[output:7fce5229] %[output:6cf19c04] %[output:8060f05e] %[output:55e3443a] %[output:252dc767] %[output:73467e26] %[output:2b974ea5] %[output:333162a1] %[output:2f48cd9f]
%%

[Sar,J0ar,GamAr,J1ar] = extract_multicut_fit_par(fit_par,en);
pd(Sar); keep_figure %[output:3e54023a]
pd(J0ar); keep_figure %[output:5c95bb35]
pd(GamAr);ly 0 200; keep_figure; %[output:8f50b737]
pd(J1ar);keep_figure; %[output:13dbec46]

